define(["core/ajax"],function(Ajax){return{transport:function(selector,query,success,failure){Ajax.call([{methodname:"local_kopere_trail_search_competencies",args:{query:query}}])[0].then(success).catch(failure)},processResults:function(selector,results){return results.map(function(result){return{value:result.id,label:result.label}})}}});